import {icon, categoryIcon} from './icons.js';
import {escapeHTML as esc, money, dateLabel, barChart, lineChart} from './charts.js';

const $ = (selector, root=document) => root.querySelector(selector);
const main = $('#main-content');
const modal = $('#modal');
const navItems = [
  ['dashboard','dashboard','Dashboard'],['import','import','Importação'],['transactions','transactions','Lançamentos'],
  ['classification','tag','Classificação'],['forecast','forecast','Previsão de caixa'],['export','export','Exportação'],
];
const pageNames = Object.fromEntries([...navItems.map(([key,,label])=>[key,label]),['settings','Minha empresa']]);
const state = {companies:[], company:null, categories:[], page:'dashboard', period:'month', summary:null,
  filters:{}, txPage:1, reviewPage:1, rows:[], selected:new Set(), preview:null, previewDirty:false,
  importSuccess:null, forecastDays:30, chartMode:'actual', latestKind:0, renderVersion:0, modalData:null, confirm:null};

async function api(path, options={}) {
  const config = {...options, headers:{...options.headers}};
  if(config.body && !(config.body instanceof FormData)){config.headers['Content-Type']='application/json';config.body=JSON.stringify(config.body);}
  let response;
  try{response=await fetch(path,config);}catch{throw new Error('Não foi possível conectar ao LoonieMind. Confira se a aplicação está aberta neste computador.');}
  const result=await response.json().catch(()=>({mensagem:'A resposta da aplicação não pôde ser lida.'}));
  if(!response.ok){
    const details=Array.isArray(result.detalhes)?result.detalhes.slice(0,3).map(x=>x.mensagem.replace(/^Value error, /,'')).join(' '):'';
    throw new Error((result.mensagem||'Não foi possível concluir a operação.')+(details?' '+details:''));
  }
  return result;
}
const endpoint = suffix => `/api/companies/${state.company.id_empresa}${suffix}`;
const params = values => new URLSearchParams(Object.entries(values).filter(([,v])=>v!==''&&v!==null&&v!==undefined&&v!==false)).toString();
const badge = (text,tone='',name='') => `<span class="badge ${tone}">${name?icon(name):''}${esc(text)}</span>`;
const button = (label,action,name='plus',kind='primary',extra='') => `<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${icon(name)}${esc(label)}</button>`;
const empty = (title,text,action='',label='Importar planilha',name='folder') => `<div class="empty-block"><div class="round-icon">${icon(name)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action?button(label,action,'import'):''}</div>`;
const dateFull = value => value?new Intl.DateTimeFormat('pt-BR').format(new Date(value.slice(0,10)+'T12:00:00')):'—';
const localToday = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const inputAmount = value => `${value<0?'-':''}${Math.floor(Math.abs(value)/100)},${String(Math.abs(value)%100).padStart(2,'0')}`;
function inputCents(value, negative=false){
  const text=String(value).trim().replace(/R\$\s*/,'').replace(/\s/g,'');
  if(!/^-?(?:\d+|\d{1,3}(?:\.\d{3})+)(?:,\d{1,2})?$/.test(text))throw new Error('Use um valor no formato brasileiro, como 1.234,56.');
  const [whole,fraction='']=text.replace(/\./g,'').replace('-','').split(',');
  let result=BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0'));
  if(text.startsWith('-'))result=-result;
  if((!negative&&result<=0n)||result>100000000000000n||result< -100000000000000n)throw new Error('Informe um valor válido dentro do limite permitido.');
  return Number(result);
}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.innerHTML=icon(error?'warning':'checkCircle')+`<span>${esc(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),error?9000:5000);}
async function busy(element,label,action){
  const old=element?.innerHTML,wasDisabled=element?.disabled;
  const workspace=$('#company-select');
  if(workspace)workspace.disabled=true;
  if(element){element.disabled=true;element.innerHTML=`<span class="spinner"></span>${esc(label)}`;}
  try{return await action();}finally{if(element?.isConnected){element.innerHTML=old;element.disabled=wasDisabled;}const select=$('#company-select');if(select)select.disabled=false;}
}
function navigate(page){const hash=`#/${page}`;if(location.hash===hash)render();else location.hash=hash;closeSidebar();$('#notification-panel').hidden=true;}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebar-backdrop').classList.remove('visible');}
function decorate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function syncShell(){
  $('#navigation').innerHTML=navItems.map(([key,name,label])=>`<a class="nav-item ${state.page===key?'active':''}" href="#/${key}" ${state.page===key?'aria-current="page"':''}>${icon(name)}${label}${key==='classification'&&state.summary?.pendentes?`<span class="nav-count">${state.summary.pendentes}</span>`:''}</a>`).join('');
  $('#settings-link').classList.toggle('active',state.page==='settings');
  $('#workspace').innerHTML=state.companies.length?`<label for="company-select">ESPAÇO DE TRABALHO</label><select id="company-select" aria-label="Selecionar empresa">${state.companies.map(c=>`<option value="${c.id_empresa}" ${c.id_empresa===state.company?.id_empresa?'selected':''}>${esc(c.nome)}${c.demo?' · Demo':''}</option>`).join('')}<option value="new">+ Nova empresa</option></select>${icon('down')}`:`<div class="workspace-empty">Seu próximo capítulo começa aqui.</div>`;
  const initials=state.company?state.company.nome.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join(''):'LM';
  $('#header-identity').innerHTML=`<div><strong>${esc(state.company?.nome||'Bem-vindo ao LoonieMind')}</strong><small>${state.company?.demo?'Ambiente de demonstração':'Seu espaço financeiro'}</small></div><div class="avatar">${esc(initials)}</div>`;
  $('#notification-dot').hidden=!state.summary?.alertas?.some(a=>['danger','warning'].includes(a.nivel));
  document.title=`${pageNames[state.page]||'Início'} · LoonieMind`;
}
async function loadCompanies(preferred){
  state.companies=await api('/api/companies');
  const saved=preferred||Number(localStorage.getItem('looniemind-company'));
  state.company=state.companies.find(c=>c.id_empresa===saved)||state.companies.find(c=>!c.demo)||state.companies[0]||null;
  if(state.company){localStorage.setItem('looniemind-company',state.company.id_empresa);state.categories=await api(endpoint('/categories'));}
  syncShell();
}
function heading(title,subtitle,actions=''){
  return `<div class="breadcrumb">LoonieMind ${icon('chevron')} <span>${esc(pageNames[state.page])}</span></div><div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>${state.company?.demo?`<div class="demo-banner">${icon('info')}<span>Você está explorando uma empresa fictícia, com dados de demonstração.</span><button type="button" data-action="new-company">Criar minha empresa ${icon('upRight')}</button></div>`:''}`;
}
function welcome(){
  return `<div class="welcome"><div class="welcome-hero"><div class="welcome-intro"><span class="eyebrow">BEM-VINDO AO LOONIEMIND</span><h1>Seu negócio merece<br><em>um futuro mais claro.</em></h1><p>Organize suas movimentações, entenda para onde seu dinheiro vai e planeje os próximos passos. Tudo em um só lugar.</p></div><div class="welcome-art" aria-hidden="true"><div class="art-circle"></div><div class="art-sheet">${icon('chart')}<div class="art-lines"></div><div class="art-lines short"></div><div class="art-bars"><i style="height:25%"></i><i style="height:50%"></i><i style="height:45%"></i><i style="height:75%"></i><i style="height:100%"></i></div></div><div class="art-leaf">${icon('leaf')}</div></div></div><div class="welcome-options"><article class="card welcome-option featured"><div class="round-icon">${icon('building')}</div><h2>Vamos começar?</h2><p>Crie o espaço da sua empresa e importe sua primeira planilha financeira.</p>${button('Criar minha empresa','new-company','arrow')}</article><article class="card welcome-option"><div class="round-icon">${icon('sparkle')}</div><h2>Conheça na prática</h2><p>Explore uma empresa fictícia com histórico, categorias e previsões já preparados.</p>${button('Explorar demonstração','demo','arrow','secondary')}</article></div><p class="welcome-note">${icon('shield')} Seus dados ficam neste computador. Sem conexão com bancos e sem envio para serviços de IA.</p></div>`;
}
function alertList(alerts){return `<ul class="alert-list">${alerts.slice(0,3).map(a=>`<li class="alert-item"><span class="alert-icon ${esc(a.nivel)}">${icon(a.nivel==='warning'?'tag':a.nivel==='danger'?'warning':a.nivel==='success'?'checkCircle':'info')}</span><div class="alert-body"><strong>${esc(a.titulo)}</strong><p>${esc(a.descricao)}</p><button type="button" data-action="navigate" data-page="${a.destino}">Ver detalhes ${icon('arrow')}</button></div></li>`).join('')}</ul>`;}
function recentList(rows){
  return rows.length?`<ul class="transaction-list">${rows.map(r=>`<li class="transaction-item"><div class="category-icon">${icon(categoryIcon(r.categoria))}</div><div class="transaction-label"><strong title="${esc(r.descricao)}">${esc(r.descricao)}</strong><small>${esc(r.categoria)}</small></div><div class="transaction-amount ${r.tipo===1?'income':''}"><strong>${r.tipo===1?'+':r.tipo===2?'−':''} ${money(r.valor_centavos)}</strong><small>${dateLabel(r.data)}</small></div></li>`).join('')}</ul>`:empty('Seu histórico começa aqui','Nenhuma movimentação neste período.','go-import');
}
async function dashboard(){
  const data=await api(endpoint('/summary')+`?periodo=${state.period}`);state.summary=data;syncShell();
  const f=data.previsao,q=data.qualidade,projected=state.chartMode==='projected',monthly=state.chartMode==='monthly';
  const periodText=`${dateFull(data.periodo.codigo==='all'?data.empresa.data_saldo:data.periodo.inicio)} a ${dateFull(data.periodo.fim)}`;
  const variation=(value)=>value===null?'Sem base de comparação':`${value>=0?'+':''}${value.toLocaleString('pt-BR')}% em relação ao período anterior`;
  const chart=projected?(f.disponivel?lineChart(f.serie):`<div class="chart-empty">${esc(f.motivo)}</div>`):monthly?barChart(data.fluxo_mensal):lineChart(data.fluxo_diario,false,'Evolução do saldo realizado');
  return heading('O que importa para o seu caixa.','Saldo, resultado e próximos passos em uma visão.',`<select id="dashboard-period" class="period-select" aria-label="Período do dashboard">${[['month','Este mês'],['30d','Últimos 30 dias'],['90d','Últimos 90 dias'],['year','Este ano'],['all','Todo o histórico']].map(([v,l])=>`<option value="${v}" ${state.period===v?'selected':''}>${l}</option>`).join('')}</select>${button('Novo lançamento','new-transaction')}`)+`
  <div class="period-context"><span>${icon('calendar')} ${periodText}</span><span>Último lançamento: ${dateFull(q.ultima_movimentacao)}</span></div>
  ${data.sem_tipo?`<div class="notice danger">${icon('warning')}<div><strong>${money(q.sem_tipo_centavos)} ainda fora do saldo.</strong> ${data.sem_tipo} lançamento(s) precisam de tipo.${button('Revisar agora','go-classification','arrow','secondary')}</div></div>`:''}
  <section class="kpi-grid" aria-label="Indicadores principais">
  <article class="card kpi balance-feature"><span>Saldo consolidado hoje ${icon('wallet')}</span><strong class="money">${money(data.saldo_centavos)}</strong><small>Saldo inicial + caixa realizado desde ${dateFull(data.empresa.data_saldo)}</small></article>
  <article class="card kpi"><span>Entradas no período ${icon('downRight')}</span><strong class="money text-teal">${money(data.receitas_centavos)}</strong><small>${variation(data.variacao_receitas)}</small></article>
  <article class="card kpi"><span>Saídas no período ${icon('upRight')}</span><strong class="money">${money(data.despesas_centavos)}</strong><small>${variation(data.variacao_despesas)}</small></article>
  <article class="card kpi"><span>Resultado do período ${icon('chart')}</span><strong class="money ${data.resultado_centavos<0?'text-red':'text-teal'}">${money(data.resultado_centavos)}</strong><small>Entradas − saídas · ${data.lancamentos_periodo.toLocaleString('pt-BR')} movimentações</small></article></section>
  <div class="dashboard-main"><section class="card chart-card"><div class="card-header"><div><h2>${projected?'Saldo projetado':monthly?'Entradas e saídas mensais':'Evolução do saldo'}</h2><p>${projected?'Próximos 30 dias · estimativa':monthly?'Últimos 6 meses · realizado':'Caixa realizado no período selecionado'}</p></div><div class="chart-tabs">${[['actual','Saldo'],['monthly','Mensal'],['projected','Projeção']].map(([value,label])=>`<button type="button" class="${state.chartMode===value?'active':''}" data-action="chart-mode" data-mode="${value}">${label}</button>`).join('')}</div></div>
  ${monthly?'<div class="chart-legend"><span><i class="legend-dot"></i>Entradas</span><span><i class="legend-dot expense"></i>Saídas</span></div>':''}${chart}
  <div class="chart-summary">${projected?f.disponivel?`<span>Saldo final estimado <strong>${money(f.saldo_final_centavos)}</strong></span><span>Menor saldo estimado <strong>${money(f.menor_saldo_centavos)}</strong></span>`:'':monthly?`<span>Comparação mensal independente do filtro acima</span>`:`<span>Saldo na abertura do gráfico <strong>${money(data.saldo_abertura_grafico_centavos)}</strong></span><span>Saldo hoje <strong>${money(data.saldo_centavos)}</strong></span>`}</div><p class="chart-footnote">${projected?'Estimativa estatística; confira os métodos e erros em Previsão de caixa.':monthly?'Lançamentos com tipo definido.':'Saldo usa a data de realização. Visualização limitada aos últimos 366 dias e à data de referência.'}</p></section>
  <aside class="card priority-panel"><span class="eyebrow">PRÓXIMOS 30 DIAS</span><h2>${f.disponivel?f.menor_saldo_centavos<0?'Seu caixa pede atenção.':'Acompanhe sua margem.':'Construa sua previsão.'}</h2>${f.disponivel?`<p>Menor saldo projetado</p><strong class="priority-value money ${f.menor_saldo_centavos<0?'text-red':''}">${money(f.menor_saldo_centavos)}</strong>${lineChart(f.serie,true)}<p class="text-small">${f.sintetico?'Estimativa sobre dados fictícios de demonstração.':'Estimativa a partir do seu histórico, sujeita a mudanças.'}</p>${button('Explorar previsão','navigate','arrow','secondary','data-page="forecast"')}`:`<p>${esc(f.motivo)}</p>${button('Importar histórico','go-import','import','secondary')}`}<div class="quality-block"><h3>Qualidade do histórico</h3><div><span>Confirmados</span><strong>${q.revisados.toLocaleString('pt-BR')}</strong></div><div><span>Para revisar</span><strong>${q.pendentes}</strong></div>${q.pendentes?button('Revisar categorias','go-classification','tag','secondary'):'<small>Revisões em dia.</small>'}</div></aside></div>
  <div class="dashboard-secondary"><section class="card latest-card"><div class="card-header"><h2>Últimas movimentações</h2><button class="subtle-button" type="button" data-action="navigate" data-page="transactions">Ver todas ${icon('chevron')}</button></div><div id="recent-list">${recentList(data.ultimos)}</div></section>
  <section class="card"><div class="card-header"><h2>Onde o dinheiro saiu</h2>${badge('No período','outline')}</div>${data.categorias.length?`<div class="category-bars">${data.categorias.slice(0,5).map((c,i)=>`<div class="category-bar-row"><span class="category-icon">${icon(categoryIcon(c.categoria))}</span><div class="category-bar-label"><div><span>${esc(c.categoria)} · ${c.percentual.toLocaleString('pt-BR')}%</span><strong>${money(c.valor_centavos)}</strong></div><div class="track"><span style="width:${Math.min(c.percentual,100)}%;opacity:${1-i*.12}"></span></div></div></div>`).join('')}</div><p class="category-total">${data.categorias.length} categorias · ${money(data.despesas_centavos)} em saídas</p>`:empty('Ainda sem despesas','As categorias aparecerão após a primeira importação.')}</section>
  <section class="card"><div class="card-header"><h2>O que precisa de atenção</h2>${icon('sparkle')}</div>${alertList(data.alertas)}</section></div>`;
}

function transactionTable(rows,review=false){
  if(!rows.length)return `<div class="table-empty">${review?'Nenhuma movimentação aguardando revisão. Tudo em dia!':'Nenhum lançamento encontrado. Ajuste os filtros ou importe uma planilha.'}</div>`;
  return `<div class="table-container"><table><thead><tr>${review?'<th><input type="checkbox" id="select-page" aria-label="Selecionar sugestões desta página"></th>':''}<th>Data</th><th>Movimentação</th><th>${review?'Categoria sugerida':'Categoria'}</th><th>Tipo</th><th class="align-right">Valor</th><th>${review?'Revisão':'Situação'}</th><th class="align-right">Ações</th></tr></thead><tbody>${rows.map(r=>`<tr>${review?`<td><input type="checkbox" data-selection="${r.id_lancamento}" aria-label="Selecionar ${esc(r.descricao)}" ${!r.sugestao?'disabled':''} ${state.selected.has(r.id_lancamento)?'checked':''}></td>`:''}<td class="money">${dateFull(r.data)}</td><td><div class="description-cell">${icon(categoryIcon(r.categoria))}<span title="${esc(r.descricao)}">${esc(r.descricao)}</span></div><span class="subline">${esc([r.contraparte,r.centro_custo,r.documento].filter(Boolean).join(' · '))}</span><span class="subline">${r.id_planilha?'Planilha · linha '+r.linha_origem:r.origem==='demonstracao'?'Dado de demonstração':'Lançamento manual'}</span></td><td ${review?'class="suggestion-cell"':''}>${review?r.sugestao?`${badge(r.sugestao.categoria,'teal',r.sugestao.metodo==='modelo'?'sparkle':'tag')}<small>${r.sugestao.metodo==='regra'?'Regra de palavra-chave':`Score do modelo: ${Math.round(r.sugestao.score*100)}%${r.sugestao.sintetico?' · treino sintético':''}`}</small>`:`<span class="muted">Sem sugestão</span>`:badge(r.categoria,r.categoria==='Sem categoria'?'warning':'')}</td><td>${badge(r.tipo===1?'Receita':r.tipo===2?'Despesa':'Definir',r.tipo===1?'teal':r.tipo===null?'warning':'')}</td><td class="align-right money ${r.tipo===1?'text-teal':''}">${r.tipo===1?'+':r.tipo===2?'−':''} ${money(r.valor_centavos)}</td><td>${review?r.sugestao?`<button class="subtle-button text-teal" type="button" data-action="accept-one" data-id="${r.id_lancamento}">${icon('check')}Confirmar</button>`:badge('Revisão manual','warning'):badge(r.revisado?'Confirmado':'Pendente',r.revisado?'':'warning',r.revisado?'check':'clock')}</td><td><div class="table-actions"><button class="icon-button" type="button" data-action="edit-transaction" data-id="${r.id_lancamento}" aria-label="Editar ${esc(r.descricao)}">${icon('edit')}</button>${!review?`<button class="icon-button delete" type="button" data-action="delete-transaction" data-id="${r.id_lancamento}" aria-label="Excluir ${esc(r.descricao)}">${icon('trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;
}
function pagination(data,review=false){const pages=Math.max(1,Math.ceil(data.total/data.por_pagina));return `<div class="table-footer"><span>${data.total?`${(data.pagina-1)*data.por_pagina+1}–${Math.min(data.pagina*data.por_pagina,data.total)} de ${data.total} lançamentos`:'0 lançamentos'}</span><div class="pagination"><button type="button" data-action="paginate" data-page="${data.pagina-1}" data-review="${review}" ${data.pagina<=1?'disabled':''}>Anterior</button><span>${data.pagina} / ${pages}</span><button type="button" data-action="paginate" data-page="${data.pagina+1}" data-review="${review}" ${data.pagina>=pages?'disabled':''}>Próxima</button></div></div>`;}
function categoryOptions(selected=''){return `<option value="">Todas as categorias</option>${[...new Set(state.categories.map(c=>c.nome))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(c=>`<option ${selected===c?'selected':''}>${esc(c)}</option>`).join('')}`;}
function filterFields(filters={}){return `<div class="field"><label for="filter-search">Pesquisar</label><input id="filter-search" name="busca" maxlength="100" value="${esc(filters.busca||'')}" placeholder="Descrição, documento ou contraparte"></div><div class="field"><label for="filter-type">Tipo</label><select id="filter-type" name="tipo"><option value="">Todos</option><option value="1" ${String(filters.tipo)==='1'?'selected':''}>Receitas</option><option value="2" ${String(filters.tipo)==='2'?'selected':''}>Despesas</option></select></div><div class="field"><label for="filter-category">Categoria</label><select id="filter-category" name="categoria">${categoryOptions(filters.categoria)}</select></div><div class="field"><label for="filter-start">De</label><input type="date" id="filter-start" name="inicio" value="${esc(filters.inicio||'')}"></div><div class="field"><label for="filter-end">Até</label><input type="date" id="filter-end" name="fim" value="${esc(filters.fim||'')}"></div>`;}
async function transactions(review=false){
  const data=await api(endpoint('/transactions')+'?'+params({...state.filters,pendentes:review,pagina:review?state.reviewPage:state.txPage}));
  state.rows=data.itens;state.selected.clear();
  let model=null;if(review)model=await api(endpoint('/model'));
  const title=review?'Cada movimentação, no lugar certo.':'Suas movimentações.';
  const subtitle=review?'Receba sugestões e confirme as categorias com a sua experiência.':'Entradas e saídas organizadas. Controle nos detalhes, clareza no todo.';
  let html=heading(title,subtitle,review?button('Gerar sugestões','classify','sparkle'):button('Importar planilha','go-import','import','secondary')+button('Novo lançamento','new-transaction'));
  if(review){html+=`<section class="card model-info"><div class="round-icon">${icon('sparkle')}</div><div class="model-info-text"><h3>${model.disponivel?'Classificação inteligente': 'Sugestões para começar'} ${badge(model.disponivel?model.sintetico?'Treino demonstrativo':'Modelo treinado':'Regras de palavras-chave',model.sintetico?'warning':'teal')}</h3><p>${model.disponivel?esc(model.aviso):'As regras iniciais ajudam a organizar seus dados. Treine um modelo com o histórico revisado para ampliar as sugestões.'} As sugestões só são aplicadas após sua confirmação.</p></div>${model.disponivel?`<div class="model-metric"><strong>${Math.round(model.metricas.f1_macro*100)}%</strong><small>F1 macro · teste interno${model.sintetico?' sintético':''}</small></div>`:''}${button('Treinar modelo','train-model','refresh','secondary')}</section>`;}
  else html+=`<div class="mini-stats"><article class="card mini-stat"><p>Entradas encontradas</p><strong class="money text-teal">${money(data.receitas_centavos)}</strong></article><article class="card mini-stat"><p>Saídas encontradas</p><strong class="money">${money(data.despesas_centavos)}</strong></article><article class="card mini-stat"><p>Movimentações</p><strong>${data.total.toLocaleString('pt-BR')}</strong></article></div>`;
  html+=`<section class="card"><form id="transaction-filters" class="filter-panel">${filterFields(state.filters)}<button class="button secondary" type="submit">${icon('filter')}Filtrar</button><button class="icon-button" type="button" data-action="reset-filters" aria-label="Limpar filtros">${icon('close')}</button></form>${review?`<div class="bulk-toolbar"><span>Selecione as sugestões que deseja aplicar.</span><button class="button secondary" type="button" data-action="accept-selected" id="accept-selected" disabled>${icon('check')}Confirmar selecionadas <span id="selected-count"></span></button></div>`:''}${transactionTable(data.itens,review)}${pagination(data,review)}</section>`;
  if(data.sem_tipo)html+=`<div class="notice">${icon('info')} ${data.sem_tipo} lançamento(s) sem tipo não entram nos totais financeiros. Informe Receita ou Despesa ao revisar.</div>`;
  return html;
}

function importHistory(rows){return `<section class="card section-block"><div class="card-header"><h2>Histórico de importações</h2><span class="section-label">${rows.length} arquivos recentes</span></div>${rows.length?`<div class="table-container"><table><thead><tr><th>Arquivo</th><th>Enviado em</th><th>Aba</th><th>Importados</th><th>Situação</th><th class="align-right">Ações</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${icon('file')} ${esc(r.nome)}${r.rejeitados?`<span class="subline">${r.rejeitados} linhas rejeitadas</span>`:''}</td><td>${dateFull(r.created_at)}</td><td>${esc(r.aba)}</td><td>${r.importados}</td><td>${badge({confirmed:'Concluída',preview:'Aguardando confirmação',undone:'Desfeita'}[r.status],r.status==='preview'?'warning':'')}</td><td class="align-right">${r.status==='confirmed'?`<button class="subtle-button" type="button" data-action="undo-import" data-id="${r.id_planilha}">Desfazer</button>`:r.status==='preview'?`<button class="subtle-button" type="button" data-action="resume-import" data-id="${r.id_planilha}">Continuar ${icon('arrow')}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:`<p class="empty-block">As planilhas que você importar vão aparecer aqui.</p>`}</section>`;}
function previewHTML(p){
  const extraNames={documento:'Documento',contraparte:'Cliente / fornecedor',centro_custo:'Centro de custo',conta:'Conta',forma_pagamento:'Forma de pagamento',competencia:'Competência',observacoes:'Observações',id_externo:'ID externo'};
  const fieldNames={data:'Data *',descricao:'Descrição *',valor:'Valor',tipo:'Tipo',categoria:'Categoria',entrada:'Entrada / Crédito',saida:'Saída / Débito'};
  return `<form id="preview-form"><div class="file-info"><span class="category-icon">${icon('file')}</span><div><h3>${esc(p.nome)}</h3><p>${p.total} linhas encontradas · ${esc(p.metadados.sheet)}</p></div><button class="subtle-button" type="button" data-action="cancel-preview" aria-label="Cancelar prévia">${icon('close')}</button></div><h3>Confira o mapeamento</h3><p class="text-small muted" style="margin:6px 0 17px">Diga o que cada coluna representa. A prévia usa as opções selecionadas abaixo.</p><div class="mapping-grid">${Object.entries(fieldNames).map(([field,label])=>`<div class="field"><label for="map-${field}">${label}</label><select id="map-${field}" data-map="${field}"><option value="">${['tipo','categoria'].includes(field)?'Não informado':'Não utilizar'}</option>${p.colunas.map(c=>`<option value="${esc(c)}" ${p.opcoes.mapping[field]===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`).join('')}</div><details class="advanced-options"><summary>Campos complementares (opcionais)</summary><div class="mapping-grid">${Object.entries(extraNames).map(([field,label])=>`<div class="field"><label for="map-${field}">${label}</label><select id="map-${field}" data-map="${field}"><option value="">Não informado</option>${p.colunas.map(c=>`<option value="${esc(c)}" ${p.opcoes.mapping[field]===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`).join('')}</div></details><details class="advanced-options"><summary>Aba, cabeçalho e formatos</summary><div class="form-grid">${p.metadados.sheets.length?`<div class="field"><label for="import-sheet">Aba</label><select id="import-sheet">${p.metadados.sheets.map(s=>`<option ${s===p.opcoes.sheet?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`:''}<div class="field"><label for="import-header">Linha do cabeçalho</label><input id="import-header" type="number" min="1" max="21" value="${p.opcoes.header_row+1}"></div><div class="field"><label for="import-decimal">Formato dos valores</label><select id="import-decimal">${[['auto','Detectar pelo conteúdo'],['br','Brasileiro · 1.234,56'],['us','Decimal · 1234.56']].map(([v,l])=>`<option value="${v}" ${p.opcoes.decimal_format===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="import-date">Formato das datas</label><select id="import-date"><option value="true" ${p.opcoes.day_first?'selected':''}>Dia / Mês / Ano</option><option value="false" ${!p.opcoes.day_first?'selected':''}>Mês / Dia / Ano</option></select></div><div class="full-width"><label class="checkbox-line"><input id="import-signed" type="checkbox" ${p.opcoes.signed_values?'checked':''}>A coluna de valor é um extrato assinado: positivo = receita, negativo = despesa.</label></div></div></details><div class="preview-actions"><span id="preview-dirty-note" class="text-small muted" hidden>Há alterações não aplicadas.</span>${button('Atualizar prévia','update-preview','refresh','secondary')}</div><div class="divider"></div><div class="preview-stats"><span><b>${p.validos}</b> válidas</span><span><b>${p.invalidos}</b> com erro</span><span><b>${p.sem_tipo}</b> sem tipo</span></div>${p.campos_ausentes.length?`<div class="notice danger">${icon('warning')}Mapeie os campos obrigatórios: ${esc(p.campos_ausentes.join(', '))}.</div>`:''}${p.duplicado?`<div class="notice danger">${icon('warning')}Esta aba deste arquivo já foi importada. Para reimportá-la, desfaça a importação anterior no histórico.</div>`:''}${p.linhas.length?`<div class="table-container bounded"><table><thead><tr><th>Linha</th><th>Data</th><th>Descrição</th><th>Tipo</th><th>Categoria</th><th class="align-right">Valor</th></tr></thead><tbody>${p.linhas.map(r=>`<tr><td>${r.linha}</td><td>${dateFull(r.data)}</td><td>${esc(r.descricao)}</td><td>${r.tipo===1?'Receita':r.tipo===2?'Despesa':badge('Definir','warning')}</td><td>${esc(r.categoria)}</td><td class="align-right money">${money(r.valor_centavos)}</td></tr>`).join('')}</tbody></table></div><p class="text-small muted" style="margin-top:10px">Mostrando até 30 linhas válidas. A confirmação processa todas as linhas da aba.</p>`:''}${p.invalidos?`<details class="advanced-options" open><summary>${p.invalidos} linhas precisam de atenção</summary><ul class="error-list">${p.erros.map(e=>`<li><strong>Linha ${e.linha}:</strong> ${esc(e.mensagem)}</li>`).join('')}</ul>${p.erros_truncados?'<p class="text-small muted">Mostrando os primeiros 200 erros.</p>':''}</details><label class="checkbox-line" style="margin-top:15px"><input type="checkbox" id="allow-partial">Importar somente as ${p.validos} linhas válidas. As ${p.invalidos} linhas com erro serão ignoradas e deverão ser corrigidas no arquivo.</label>`:''}${p.possiveis_duplicados?`<div class="notice">${icon('info')}<div>${p.possiveis_duplicados} linhas são semelhantes a movimentações existentes. Podem ser transações legítimas.<label class="checkbox-line" style="margin-top:8px"><input type="checkbox" id="keep-similar">Conferi os dados e quero manter essas movimentações.</label></div></div>`:''}${p.sem_tipo?`<div class="notice info">${icon('info')}Linhas sem tipo ficarão pendentes de revisão e não serão somadas ao saldo até serem classificadas.</div>`:''}<div class="preview-actions">${button('Cancelar','cancel-preview','close','secondary')}<button type="button" class="button primary" data-action="confirm-import" id="confirm-import" ${p.campos_ausentes.length||!p.validos||p.duplicado||p.invalidos||p.possiveis_duplicados?'disabled':''}>${icon('check')}Confirmar importação</button></div></form>`;
}
async function importPage(){
  const history=await api(endpoint('/imports'));
  return heading('Traga seus números para perto.','Da planilha para uma visão organizada. Sem complicar o que já faz parte da sua rotina.')+`<div class="page-grid"><section class="card card-padding"><div class="stepper"><span class="${!state.preview&&!state.importSuccess?'active':''}"><b>1</b>Enviar arquivo</span><i></i><span class="${state.preview?'active':''}"><b>2</b>Conferir dados</span><i></i><span class="${state.importSuccess?'active':''}"><b>3</b>Concluir</span></div>${state.preview?previewHTML(state.preview):state.importSuccess?`<div class="success-panel"><div class="round-icon">${icon('checkCircle')}</div><h2>Pronto. Seus dados estão aqui.</h2><p>${state.importSuccess.importados} lançamentos importados${state.importSuccess.rejeitados?` · ${state.importSuccess.rejeitados} linhas rejeitadas`:''}.</p><div class="success-actions">${button('Revisar categorias','go-classification','tag')}${button('Ver lançamentos','go-transactions','arrow','secondary')}</div><button class="subtle-button" type="button" data-action="another-import" style="margin-top:20px">Importar outro arquivo</button></div>`:`<label class="upload-zone" id="upload-zone"><div class="round-icon">${icon('upload')}</div><h3>Arraste sua planilha até aqui</h3><p>ou escolha um arquivo no seu computador</p><span class="button primary">${icon('plus')}Selecionar arquivo</span><small>CSV, XLS ou XLSX · Até 10 MB e 10.000 linhas por aba</small><input type="file" id="import-file" accept=".csv,.xls,.xlsx" aria-label="Selecionar planilha financeira"></label>`}</section><div class="stack"><section class="card card-padding"><h2>Uma boa importação começa aqui</h2><ul class="guide-list"><li>${icon('check')}<div><strong>Mais contexto, mais controle</strong><br>Data, descrição e valor, além de documento, conta, centro de custo e contraparte.</div></li><li>${icon('check')}<div><strong>Entradas e saídas claras</strong><br>Use uma coluna de tipo ou separe os valores de entrada e saída.</div></li><li>${icon('check')}<div><strong>Categorias são bem-vindas</strong><br>Se ainda não tiver, você pode revisar depois com sugestões.</div></li></ul><div class="help-box">${icon('shield')}A prévia não altera seu histórico. Os lançamentos só são gravados ao confirmar.</div></section><section class="card card-padding"><h3>Precisa de um ponto de partida?</h3><p class="text-small muted" style="margin-top:8px">13 campos, validação de preenchimento e 240 exemplos fictícios em aba separada. Preencha a aba Movimentacoes com seus dados. O CSV contém exemplos fictícios.</p><div class="sample-links"><a href="/api/template?formato=xlsx">${icon('download')}Modelo Excel</a><a href="/api/template?formato=csv">${icon('download')}Modelo CSV</a></div></section></div></div>${importHistory(history)}`;
}

async function forecastPage(){
  const f=await api(endpoint('/forecast')+`?dias=${state.forecastDays}`);
  const exportAction=f.disponivel?`<a class="button secondary" href="${endpoint('/forecast/export')}?dias=${state.forecastDays}&formato=xlsx">${icon('download')}Exportar projeção</a>`:`<button class="button secondary" type="button" disabled title="Importe histórico suficiente para gerar uma previsão.">${icon('download')}Exportar projeção</button>`;
  let html=heading('Um passo à frente.','Explore o que seu histórico indica para o futuro do caixa.',`<select id="forecast-days" class="period-select" aria-label="Horizonte da previsão">${[7,30,60,90].map(n=>`<option value="${n}" ${state.forecastDays===n?'selected':''}>Próximos ${n} dias</option>`).join('')}</select>${exportAction}`);
  if(!f.disponivel)return html+`<section class="card">${empty('Vamos construir essa perspectiva?',f.motivo,'go-import','Importar histórico','calendar')}</section><div class="notice info">${icon('info')}Com 28 dias de histórico recente, uma referência sazonal fica disponível. A partir de 90 dias, o LightGBM também é avaliado.</div>`;
  const income=f.serie.reduce((s,r)=>s+r.receitas_centavos,0),expense=f.serie.reduce((s,r)=>s+r.despesas_centavos,0);
  return html+`<div class="forecast-metrics">${[['Saldo ao final da projeção',f.saldo_final_centavos,''],['Menor saldo previsto',f.menor_saldo_centavos,f.menor_saldo_centavos<0?'text-red':''],['Entradas previstas',income,'text-teal'],['Saídas previstas',expense,'']].map(([label,value,cls])=>`<article class="card mini-stat"><p>${label}</p><strong class="money ${cls}">${money(value)}</strong></article>`).join('')}</div><section class="card"><div class="card-header"><div><h2>Para onde o caixa pode ir</h2><p>${state.forecastDays} dias de projeção · ${f.dias_historico} dias de histórico</p></div>${badge(f.menor_saldo_centavos<0?'Atenção ao saldo':'Caixa projetado positivo',f.menor_saldo_centavos<0?'danger':'teal')}</div>${lineChart(f.serie)}<div class="forecast-method"><span>${icon('calendar')}Base até ${dateFull(f.origem_previsao)}</span><span>${icon('sparkle')}${esc(f.metodo)}</span></div></section><div class="notice info">${icon('info')}${esc(f.aviso)}${f.pendentes_sem_tipo?` ${f.pendentes_sem_tipo} lançamento(s) sem tipo foram excluídos dos cálculos.`:''}</div><div class="forecast-info"><section class="card card-padding methodology"><h3>Como chegamos a essa projeção</h3><p>Receitas e despesas são estimadas separadamente. O sistema compara o LightGBM com a repetição do padrão de 7 dias e usa o método com menor erro no período de teste.</p><p>Datas futuras são calculadas em sequência, sem usar dados do futuro. A previsão é recalculada quando você altera o histórico ou o saldo inicial.</p><p>${f.sintetico?'Este histórico é sintético e serve para demonstração. A qualidade em uma empresa real precisa ser avaliada com dados reais.':'Um único teste histórico não garante os resultados futuros. Confira a cobertura das planilhas e acompanhe o caixa realizado.'}</p></section><section class="card"><div class="card-header"><h2>Transparência dos modelos</h2></div><div class="table-container" style="margin-top:17px"><table><thead><tr><th>Série</th><th>Método escolhido</th><th class="align-right">Erro médio no teste</th></tr></thead><tbody>${Object.entries(f.modelos).map(([name,m])=>`<tr><td>${name==='receitas'?'Receitas':'Despesas'}</td><td>${esc(m.metodo)}${m.avaliacao?`<span class="subline">${m.avaliacao.dias_teste} dias · ${dateLabel(m.avaliacao.inicio_teste)} a ${dateLabel(m.avaliacao.fim_teste)}</span>`:'<span class="subline">Histórico ainda curto para comparar modelos</span>'}</td><td class="align-right">${m.avaliacao?money(Math.min(m.avaliacao.mae_modelo_centavos,m.avaliacao.mae_referencia_centavos)):'—'}</td></tr>`).join('')}</tbody></table></div><p class="chart-footnote" style="padding-bottom:20px">MAE: diferença média absoluta entre valor previsto e realizado no teste. Menor é melhor.</p></section></div><section class="card section-block"><div class="card-header" style="padding-bottom:18px"><h2>Dia a dia, com mais clareza</h2><span class="section-label">Valores estimados</span></div><div class="table-container bounded"><table><thead><tr><th>Data</th><th class="align-right">Receitas</th><th class="align-right">Despesas</th><th class="align-right">Saldo acumulado</th></tr></thead><tbody>${f.serie.map(r=>`<tr><td>${dateFull(r.data)}</td><td class="align-right text-teal money">${money(r.receitas_centavos)}</td><td class="align-right money">${money(r.despesas_centavos)}</td><td class="align-right money ${r.saldo_centavos<0?'text-red':''}">${money(r.saldo_centavos)}</td></tr>`).join('')}</tbody></table></div></section>`;
}

async function exportPage(){
  const [count,materials]=await Promise.all([api(endpoint('/transactions')+'?por_pagina=1'),api('/api/materials')]);
  return heading('Seus dados, do seu jeito.','Leve o histórico e as projeções para sua planilha. Organizados e prontos para usar.')+`<div class="page-grid"><section class="card card-padding"><form id="export-form"><h2>O que você quer exportar?</h2><div class="export-choices"><label class="choice"><input type="radio" name="conteudo" value="transactions" checked>${icon('transactions')}<strong>Lançamentos</strong><small>Movimentações, categorias e situação da revisão.</small></label><label class="choice"><input type="radio" name="conteudo" value="forecast">${icon('forecast')}<strong>Previsão de caixa</strong><small>Entradas, saídas e saldo estimados para os próximos dias.</small></label></div><div id="export-filters" class="form-grid"><div class="field"><label for="export-start">Data inicial</label><input type="date" name="inicio" id="export-start"></div><div class="field"><label for="export-end">Data final</label><input type="date" name="fim" id="export-end"></div><div class="field"><label for="export-type">Tipo</label><select name="tipo" id="export-type"><option value="">Todos os tipos</option><option value="1">Receitas</option><option value="2">Despesas</option></select></div><div class="field"><label for="export-category">Categoria</label><select name="categoria" id="export-category">${categoryOptions()}</select></div></div><div id="export-horizon" class="field" hidden><label for="export-days">Horizonte da previsão</label><select name="dias" id="export-days">${[7,30,60,90].map(n=>`<option value="${n}" ${n===30?'selected':''}>Próximos ${n} dias</option>`).join('')}</select></div><h3 style="margin-top:26px">Escolha o formato</h3><div class="format-choices"><label class="format-choice"><input type="radio" name="formato" value="xlsx" checked>Excel · .xlsx</label><label class="format-choice"><input type="radio" name="formato" value="csv">CSV · .csv</label></div><div class="export-bottom"><small>O histórico tem ${count.total} movimentações.<br>Os filtros serão aplicados antes de gerar o arquivo.</small><button class="button primary" type="submit">${icon('download')}Exportar arquivo</button></div></form></section><div class="stack"><section class="card card-padding"><h2>Pronto para continuar</h2><ul class="guide-list"><li>${icon('file')}<div><strong>Excel</strong><br>Resumo, análise mensal, categorias, centros de custo e lançamentos completos. A projeção inclui os métodos e erros de validação.</div></li><li>${icon('file')}<div><strong>CSV</strong><br>Compatível com outros sistemas. Separado por ponto e vírgula e com valores em formato brasileiro.</div></li><li>${icon('shield')}<div><strong>Dados rastreáveis</strong><br>Os lançamentos incluem a referência da importação e a linha original.</div></li></ul></section></div></div>${materials.length?`<section class="card card-padding section-block"><h2>Materiais do LoonieMind</h2><p class="text-small muted">Funcionamento, IA, apresentação e exemplos fictícios para explorar a aplicação.</p><div class="materials-grid">${materials.map(m=>`<a href="${esc(m.url)}" class="material-link">${icon('download')}<span>${esc(m.nome)}<small>${esc(m.formato.toUpperCase())}</small></span>${icon('arrow')}</a>`).join('')}</div></section>`:''}<section class="card backup-card"><div class="round-icon">${icon('shield')}</div><div><h3>Um cuidado a mais com o seu histórico</h3><p>O backup inclui todas as empresas, o histórico de alterações e as planilhas originais. Guarde o ZIP em um local seguro.</p></div><a class="button secondary" href="/api/backup">${icon('download')}Baixar backup completo</a></section>`;
}

async function settingsPage(){
  state.companies=await api('/api/companies');
  state.company=state.companies.find(c=>c.id_empresa===state.company.id_empresa)||state.company;
  state.categories=await api(endpoint('/categories'));
  const audit=await api(endpoint('/audit'));
  const names={criar_empresa:'Empresa criada',alterar_empresa:'Dados da empresa alterados',importar:'Planilha importada',desfazer_importacao:'Importação desfeita',criar_lancamento:'Lançamento criado',corrigir_lancamento:'Lançamento corrigido',excluir_lancamento:'Lançamento excluído',treinar_modelo:'Modelo treinado',sugerir_classificacao:'Sugestões geradas',aceitar_sugestao:'Sugestão confirmada',carregar_demonstracao:'Demonstração preparada',criar_categoria:'Categoria criada'};
  return heading('Um espaço para cada negócio.','Organize suas empresas, ajuste o saldo de referência e acompanhe as alterações.',button('Base ampliada','expanded-demo','sparkle','secondary')+button('Nova empresa','new-company','plus'))+`<div class="company-grid">${state.companies.map(c=>`<article class="card company-card ${c.id_empresa===state.company.id_empresa?'current':''}"><div class="flex-between w-full"><div class="round-icon">${icon('building')}</div>${c.demo?badge('Demonstração','warning'):badge('Empresa','outline')}</div><div><h3>${esc(c.nome)}</h3><p>${esc(c.descricao||'Seu espaço financeiro local.')}</p></div><div class="company-card-bottom"><small>${c.total_lancamentos??0} movimentações</small>${c.id_empresa===state.company.id_empresa?button('Editar','edit-company','edit','secondary'):`<button type="button" class="button secondary" data-action="switch-company" data-id="${c.id_empresa}">Acessar ${icon('arrow')}</button>`}</div></article>`).join('')}</div><div class="settings-split"><section class="card card-padding"><div class="flex-between"><h2>Saldo de referência</h2>${button('Ajustar','edit-company','edit','secondary')}</div><div class="settings-facts"><div><span>Saldo inicial</span><strong class="money">${money(state.company.saldo_inicial_centavos)}</strong></div><div><span>Data de referência</span><strong>${dateFull(state.company.data_saldo)}</strong></div><div><span>Moeda</span><strong>Real brasileiro · BRL</strong></div><div><span>Armazenamento</span><strong>Neste computador</strong></div></div><div class="help-box">${icon('info')}O saldo atual considera o saldo inicial e as movimentações realizadas a partir da data de referência, incluindo esse dia. Movimentações anteriores continuam no histórico.</div></section><section class="card card-padding"><div class="flex-between"><h2>Suas categorias</h2>${button('Adicionar','new-category','plus','secondary')}</div><div class="category-tags">${state.categories.map(c=>badge(c.nome,c.tipo===1?'teal':'')).join('')}</div><p class="text-small muted" style="margin-top:17px">Categorias de receita e despesa são separadas. Novos nomes podem ser definidos ao revisar um lançamento.</p></section></div><section class="card section-block"><div class="card-header" style="padding-bottom:18px"><h2>Histórico de alterações</h2><span class="section-label">Últimas ${Math.min(audit.length,30)} ações</span></div><div class="table-container"><table><thead><tr><th>Quando</th><th>Ação</th><th>Referência</th><th>Detalhes</th></tr></thead><tbody>${audit.slice(0,30).map(r=>`<tr><td>${new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(r.created_at))}</td><td>${esc(names[r.acao]||r.acao)}</td><td>${esc(r.entidade)} ${esc(r.referencia)}</td><td><details class="audit-details"><summary>Ver registro</summary><pre>${esc(JSON.stringify(r.detalhes,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div></section>`;
}

async function render(){
  const token=++state.renderVersion;
  state.page=(location.hash.replace(/^#\/?/,'').split('?')[0]||'dashboard');
  if(!pageNames[state.page])state.page='dashboard';
  syncShell();
  if(!state.company){main.innerHTML=welcome();return;}
  main.innerHTML='<div class="loading-view"><span class="spinner"></span><p>Organizando sua perspectiva...</p></div>';
  try{
    const views={dashboard,import:importPage,transactions:()=>transactions(false),classification:()=>transactions(true),forecast:forecastPage,export:exportPage,settings:settingsPage};
    const html=await views[state.page]();
    if(token!==state.renderVersion)return;
    main.innerHTML=html;
    if(state.page==='dashboard'&&state.latestKind)updateLatest(state.latestKind);
  }catch(error){if(token===state.renderVersion)main.innerHTML=`<div class="fatal-view">${icon('warning')}<h2>Não foi possível carregar esta visão.</h2><p>${esc(error.message)}</p>${button('Tentar novamente','retry','refresh','secondary')}</div>`;}
}

function openForm(id,title,subtitle,content,submit='Salvar',data=null){
  state.modalData=data;
  modal.innerHTML=`<form id="${id}"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="icon-button" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div><div class="modal-content">${content}<p class="form-error" id="form-error" hidden></p></div><div class="modal-footer"><button type="button" class="button secondary" data-action="close-modal">Cancelar</button><button type="submit" class="button primary">${icon('check')}${esc(submit)}</button></div></form>`;
  if(!modal.open)modal.showModal();
}
function companyForm(edit=false){
  const c=edit?state.company:null;
  openForm('company-form',edit?'Ajuste seu espaço':'Conte um pouco sobre sua empresa','Um nome, um saldo de referência e um novo começo.',`<div class="form-grid"><div class="field full-width"><label for="company-name">Nome da empresa</label><input id="company-name" name="nome" required minlength="2" maxlength="100" value="${esc(c?.nome||'')}" placeholder="Ex.: Ateliê Horizonte" autofocus></div><div class="field full-width"><label for="company-description">Descrição <span class="muted">· opcional</span></label><textarea id="company-description" name="descricao" maxlength="300" placeholder="O que faz o seu negócio?">${esc(c?.descricao||'')}</textarea></div><div class="field"><label for="company-balance">Saldo inicial (R$)</label><input id="company-balance" name="saldo" inputmode="decimal" required value="${inputAmount(c?.saldo_inicial_centavos||0)}"><small>Formato brasileiro · pode ser negativo</small></div><div class="field"><label for="company-date">Data de referência</label><input id="company-date" name="data_saldo" type="date" required max="${localToday()}" value="${c?.data_saldo||localToday().slice(0,4)+'-01-01'}"></div></div><div class="notice info">${icon('info')}Informe o saldo antes das movimentações da data escolhida. As entradas e saídas a partir desse dia serão somadas a ele.</div>`,edit?'Salvar alterações':'Criar empresa',{edit});
}
function transactionForm(row=null){
  const category=row?.categoria==='Sem categoria'?(row?.sugestao?.categoria||''):row?.categoria||'';
  openForm('transaction-form',row?'Revise esta movimentação':'Uma nova movimentação','Registre o que aconteceu. Seu histórico fica atualizado na hora.',`<div class="form-grid"><div class="field full-width"><label for="transaction-description">Descrição</label><input id="transaction-description" name="descricao" required maxlength="250" value="${esc(row?.descricao||'')}" placeholder="Ex.: Compra de materiais" autofocus></div><div class="field"><label for="transaction-amount">Valor (R$)</label><input id="transaction-amount" name="valor" inputmode="decimal" required value="${row?inputAmount(row.valor_centavos):''}" placeholder="0,00"><small>Valor positivo · formato 1.234,56</small></div><div class="field"><label for="transaction-type">Tipo</label><select id="transaction-type" name="tipo" required><option value="">Selecione</option><option value="1" ${(row?.tipo||row?.sugestao?.tipo)===1?'selected':''}>Receita · entrada</option><option value="2" ${(row?.tipo||row?.sugestao?.tipo)===2?'selected':''}>Despesa · saída</option></select></div><div class="field"><label for="transaction-date">Data realizada</label><input id="transaction-date" name="data" type="date" required max="${localToday()}" value="${row?.data||localToday()}"></div><div class="field"><label for="transaction-category">Categoria</label><input id="transaction-category" name="categoria" list="category-names" required maxlength="80" value="${esc(category)}" placeholder="Escolha ou digite um nome"><datalist id="category-names">${[...new Set(state.categories.map(c=>c.nome))].map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist><small>Um novo nome cria uma categoria.</small></div></div><details class="advanced-options"><summary>Documento, conta e informações complementares</summary><div class="form-grid">${[['documento','Documento',80],['contraparte','Cliente / fornecedor',120],['centro_custo','Centro de custo',80],['conta','Conta',80],['forma_pagamento','Forma de pagamento',60],['competencia','Competência (AAAA-MM)',10],['id_externo','ID externo',100],['observacoes','Observações',500]].map(([key,label,limit])=>`<div class="field"><label for="detail-${key}">${label}</label><input id="detail-${key}" name="${key}" maxlength="${limit}" value="${esc(row?.[key]||'')}"></div>`).join('')}</div></details>`,row?'Confirmar revisão':'Adicionar lançamento',row);
}
function confirmDialog(title,text,action,label='Confirmar'){
  state.confirm=action;
  openForm('confirm-form',title,'Confira antes de continuar.',`<p class="help-paragraph">${esc(text)}</p>`,label);
}
function trainForm(){
  openForm('train-form','Aprender com os seus dados','Escolha a base para treinar a classificação.',`<label class="choice"><input type="radio" name="fonte" value="reviewed" checked>${icon('tag')}<strong>Histórico revisado desta empresa</strong><small>Usa categorias confirmadas. Mínimo de 24 exemplos, duas classes e quatro descrições distintas por classe.</small></label><label class="choice"><input type="radio" name="fonte" value="synthetic">${icon('sparkle')}<strong>Base sintética de demonstração</strong><small>Ajuda a explorar o recurso. Não comprova qualidade em dados reais e será identificada na interface.</small></label><p class="help-paragraph">O modelo anterior será substituído. As movimentações já confirmadas serão preservadas.</p>`,'Treinar modelo');
}
function showHelp(){
  openForm('help-form','Uma rotina mais clara','Guia rápido para aproveitar o LoonieMind.',`<h3 class="help-heading">1. Prepare seu espaço</h3><p class="help-paragraph">Crie uma empresa e informe o saldo antes das primeiras movimentações. Você pode alternar entre empresas sem misturar os dados.</p><h3 class="help-heading">2. Importe e confira</h3><p class="help-paragraph">Envie CSV, XLS ou XLSX. Confirme quais colunas representam data, descrição, valor e tipo. A prévia mostra problemas antes da gravação.</p><h3 class="help-heading">3. Revise suas categorias</h3><p class="help-paragraph">Em Classificação, gere sugestões e confirme o que fizer sentido. O score do modelo é um sinal de classificação, não uma garantia de acerto.</p><h3 class="help-heading">4. Olhe para a frente</h3><p class="help-paragraph">A previsão precisa de 28 dias de histórico recente. A partir de 90 dias, com movimentações suficientes, o LightGBM é comparado com uma referência sazonal.</p><h3 class="help-heading">5. Cuide do histórico</h3><p class="help-paragraph">Baixe um backup completo em Exportação. O <a href="/api/materials/manual" target="_blank" rel="noopener">manual do sistema e da IA</a> explica como restaurá-lo em uma pasta separada. O arquivo inclui todas as empresas.</p><div class="notice info">${icon('shield')}A aplicação funciona localmente. Não acessa bancos, não efetua pagamentos e não envia suas planilhas para serviços de IA.</div>`,'Entendi');
}

function collectPreviewOptions(){
  const mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,el.value]));
  const options={mapping,header_row:Number($('#import-header').value)-1,decimal_format:$('#import-decimal').value,
    day_first:$('#import-date').value==='true',signed_values:$('#import-signed').checked};
  if($('#import-sheet'))options.sheet=$('#import-sheet').value;
  if(options.sheet!==state.preview.opcoes.sheet||options.header_row!==state.preview.opcoes.header_row)options.mapping=null;
  return options;
}
function updateConfirm(){const p=state.preview,b=$('#confirm-import');if(!b||!p)return;b.disabled=!!(state.previewDirty||p.campos_ausentes.length||!p.validos||p.duplicado||(p.invalidos&&!$('#allow-partial')?.checked)||(p.possiveis_duplicados&&!$('#keep-similar')?.checked));}
async function uploadFile(file){
  if(!file)return;if(file.size>10*1024*1024)throw new Error('O arquivo deve ter no máximo 10 MB.');
  const companyId=state.company.id_empresa;
  const data=new FormData();data.append('arquivo',file);data.append('opcoes','{}');
  const zone=$('#upload-zone');
  await busy(zone,'Lendo e validando sua planilha...',async()=>{const preview=await api(`/api/companies/${companyId}/imports`,{method:'POST',body:data});if(state.company?.id_empresa===companyId){state.preview=preview;state.previewDirty=false;state.importSuccess=null;await render();}});
}
async function updateLatest(kind){
  state.latestKind=kind;
  const filters={tipo:kind||'',por_pagina:5,inicio:state.summary?.periodo.inicio,fim:state.summary?.periodo.fim};
  const company=state.company.id_empresa;
  const data=await api(endpoint('/transactions')+'?'+params(filters));
  if(state.page!=='dashboard'||company!==state.company?.id_empresa)return;
  const container=$('#recent-list');if(container)container.innerHTML=recentList(data.itens);
  document.querySelectorAll('[data-action="latest-filter"]').forEach(el=>el.classList.toggle('active',Number(el.dataset.kind)===kind));
}
async function accept(ids,el){await busy(el,'Confirmando...',async()=>{const r=await api(endpoint('/classify/accept'),{method:'POST',body:{ids}});toast(`${r.confirmados} sugestão(ões) confirmada(s).`);state.summary=null;await render();});}
function selectedUI(){const b=$('#accept-selected');if(b)b.disabled=!state.selected.size;const n=$('#selected-count');if(n)n.textContent=state.selected.size?`(${state.selected.size})`:'';}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  const action=el.dataset.action;
  try{
    if(action==='navigate'){navigate(el.dataset.page);return;}
    if(action.startsWith('go-')){navigate({'go-import':'import','go-classification':'classification','go-transactions':'transactions'}[action]);return;}
    if(action==='menu'){$('#sidebar').classList.toggle('open');$('#sidebar-backdrop').classList.toggle('visible');return;}
    if(action==='help'){showHelp();return;}
    if(action==='close-modal'){modal.close();return;}
    if(action==='retry'){if(!state.companies.length)await loadCompanies();await render();return;}
    if(action==='new-company'){companyForm();return;}
    if(action==='edit-company'){companyForm(true);return;}
    if(action==='expanded-demo'){await busy(el,'Preparando cenários...',async()=>{const result=await api('/api/demo/expanded',{method:'POST'});await loadCompanies(result.empresas[0].empresa.id_empresa);toast('Três cenários fictícios disponíveis. Treine a classificação na tela Classificação.');await render();});return;}
    if(action==='new-transaction'){transactionForm();return;}
    if(action==='edit-transaction'){const row=state.rows.find(r=>r.id_lancamento===Number(el.dataset.id));if(row)transactionForm(row);return;}
    if(action==='demo'){await busy(el,'Préparando a demonstração...',async()=>{const r=await api('/api/demo',{method:'POST'});await loadCompanies(r.empresa.id_empresa);toast('Seu espaço de demonstração está pronto.');navigate('dashboard');});return;}
    if(action==='switch-company'){await selectCompany(Number(el.dataset.id));return;}
    if(action==='delete-transaction'){const row=state.rows.find(r=>r.id_lancamento===Number(el.dataset.id));confirmDialog('Excluir esta movimentação?',`“${row.descricao}”, no valor de ${money(row.valor_centavos)}, será removida do histórico. A alteração será registrada.`,async()=>{await api(endpoint('/transactions/')+row.id_lancamento,{method:'DELETE'});toast('Movimentação excluída.');await render();},'Excluir lançamento');return;}
    if(action==='reset-filters'){state.filters={};state.txPage=state.reviewPage=1;await render();return;}
    if(action==='paginate'){if(el.dataset.review==='true')state.reviewPage=Number(el.dataset.page);else state.txPage=Number(el.dataset.page);await render();return;}
    if(action==='chart-mode'){state.chartMode=el.dataset.mode;await render();return;}
    if(action==='latest-filter'){await updateLatest(Number(el.dataset.kind));return;}
    if(action==='classify'){await busy(el,'Analisando movimentações...',async()=>{const r=await api(endpoint('/classify'),{method:'POST'});toast(`${r.sugestoes} sugestões preparadas para revisão.`);await render();});return;}
    if(action==='accept-one'){await accept([Number(el.dataset.id)],el);return;}
    if(action==='accept-selected'){await accept([...state.selected],el);return;}
    if(action==='train-model'){trainForm();return;}
    if(action==='new-category'){openForm('category-form','Uma nova categoria','Um nome que faça sentido para o seu negócio.',`<div class="form-grid"><div class="field"><label for="category-name">Nome</label><input id="category-name" name="nome" required minlength="2" maxlength="80" autofocus></div><div class="field"><label for="category-type">Tipo</label><select id="category-type" name="tipo"><option value="2">Despesa</option><option value="1">Receita</option></select></div></div>`,'Criar categoria');return;}
    if(action==='update-preview'){await busy(el,'Atualizando...',async()=>{state.preview=await api(endpoint(`/imports/${state.preview.id_planilha}/preview`),{method:'POST',body:collectPreviewOptions()});state.previewDirty=false;await render();});return;}
    if(action==='cancel-preview'){state.preview=null;state.previewDirty=false;await render();return;}
    if(action==='confirm-import'){const company=state.company.id_empresa;const payload={permitir_parcial:!!$('#allow-partial')?.checked,manter_semelhantes:!!$('#keep-similar')?.checked};await busy(el,'Importando...',async()=>{const r=await api(`/api/companies/${company}/imports/${state.preview.id_planilha}/confirm`,{method:'POST',body:payload});state.preview=null;state.importSuccess=r;state.summary=null;await loadCompanies(company);toast(`${r.importados} lançamentos adicionados ao histórico.`);await render();});return;}
    if(action==='another-import'){state.importSuccess=null;await render();return;}
    if(action==='resume-import'){await busy(el,'Abrindo prévia...',async()=>{state.preview=await api(endpoint(`/imports/${el.dataset.id}/preview`),{method:'POST',body:{}});state.previewDirty=false;state.importSuccess=null;await render();});return;}
    if(action==='undo-import'){const id=el.dataset.id;confirmDialog('Desfazer esta importação?','Todos os lançamentos dessa importação serão removidos, inclusive os que você corrigiu depois. O arquivo e o registro da ação serão preservados. Você poderá importar o arquivo novamente.',async()=>{const r=await api(endpoint(`/imports/${id}/undo`),{method:'POST'});state.summary=null;toast(`${r.removidos} lançamentos removidos.`);await render();},'Desfazer importação');return;}
    if(action==='notifications'){if(!state.company){toast('Crie ou escolha uma empresa para acompanhar os alertas.');return;}const panel=$('#notification-panel');if(!panel.hidden){panel.hidden=true;return;}await busy(el,'',async()=>{const data=state.summary||await api(endpoint('/summary'));panel.innerHTML=`<h3>Seu negócio pede atenção a...</h3>${alertList(data.alertas)}`;panel.hidden=false;});return;}
  }catch(error){toast(error.message,true);}
});

document.addEventListener('submit',async event=>{
  const form=event.target;event.preventDefault();
  const values=Object.fromEntries(new FormData(form));
  const submit=form.querySelector('button[type="submit"]');
  const errorBox=$('#form-error',form);
  if(errorBox){errorBox.hidden=true;errorBox.textContent='';}
  try{
    if(form.id==='global-search'){state.filters={busca:values.busca};state.txPage=1;navigate('transactions');return;}
    if(form.id==='transaction-filters'){state.filters=values;state.txPage=state.reviewPage=1;await render();return;}
    if(form.id==='help-form'){modal.close();return;}
    if(form.id==='confirm-form'){const confirm=state.confirm;await busy(submit,'Confirmando...',confirm);modal.close();return;}
    if(form.id==='company-form'){
      const payload={nome:values.nome,descricao:values.descricao,saldo_inicial_centavos:inputCents(values.saldo,true),data_saldo:values.data_saldo};
      const edit=state.modalData?.edit;
      await busy(submit,'Salvando...',async()=>{const c=await api(edit?endpoint(''):'/api/companies',{method:edit?'PUT':'POST',body:payload});state.summary=null;await loadCompanies(c.id_empresa);state.preview=null;state.importSuccess=null;state.filters={};modal.close();toast(edit?'Dados da empresa atualizados.':'Seu espaço está pronto. Vamos começar!');navigate(edit?'settings':'dashboard');});return;
    }
    if(form.id==='transaction-form'){
      const id=state.modalData?.id_lancamento;
      const payload={...Object.fromEntries(['documento','contraparte','centro_custo','conta','forma_pagamento','competencia','observacoes','id_externo'].map(k=>[k,values[k]||''])),descricao:values.descricao,categoria:values.categoria,tipo:Number(values.tipo),data:values.data,valor_centavos:inputCents(values.valor)};
      await busy(submit,'Salvando...',async()=>{await api(endpoint('/transactions')+(id?`/${id}`:''),{method:id?'PUT':'POST',body:payload});state.categories=await api(endpoint('/categories'));state.summary=null;modal.close();toast(id?'Revisão salva no histórico.':'Movimentação adicionada.');await render();});return;
    }
    if(form.id==='category-form'){await busy(submit,'Criando...',async()=>{state.categories=await api(endpoint('/categories'),{method:'POST',body:{nome:values.nome,tipo:Number(values.tipo)}});modal.close();toast('Categoria criada.');await render();});return;}
    if(form.id==='train-form'){await busy(submit,'Treinando e avaliando...',async()=>{const r=await api(endpoint('/model/train'),{method:'POST',body:{fonte:values.fonte}});modal.close();toast(`Modelo treinado com ${r.exemplos} exemplos. Agora você pode gerar sugestões.`);await render();});return;}
    if(form.id==='export-form'){
      const isForecast=values.conteudo==='forecast';
      const query=params(isForecast?{formato:values.formato,dias:values.dias}:{formato:values.formato,inicio:values.inicio,fim:values.fim,tipo:values.tipo,categoria:values.categoria});
      const url=endpoint(isForecast?'/forecast/export':'/export')+'?'+query;
      await busy(submit,'Preparando arquivo...',async()=>{const response=await fetch(url);if(!response.ok){const error=await response.json();throw new Error(error.mensagem||'Não foi possível exportar.');}const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`looniemind-${isForecast?'previsao':'lancamentos'}-${localToday()}.${values.formato}`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),15000);toast('Arquivo exportado. Confira seus downloads.');});return;
    }
  }catch(error){if(errorBox){errorBox.textContent=error.message;errorBox.hidden=false;}else toast(error.message,true);}
});

async function selectCompany(id){
  const company=state.companies.find(c=>c.id_empresa===id);if(!company)return;
  state.company=company;localStorage.setItem('looniemind-company',id);state.categories=await api(endpoint('/categories'));
  state.summary=null;state.preview=null;state.importSuccess=null;state.filters={};state.txPage=state.reviewPage=1;state.selected.clear();
  $('#notification-panel').hidden=true;await render();
}
document.addEventListener('change',async event=>{
  const el=event.target;
  try{
    if(el.id==='company-select'){if(el.value==='new'){el.value=String(state.company.id_empresa);companyForm();}else await selectCompany(Number(el.value));}
    if(el.id==='dashboard-period'){state.period=el.value;await render();}
    if(el.id==='forecast-days'){state.forecastDays=Number(el.value);await render();}
    if(el.id==='import-file')await uploadFile(el.files[0]);
    if(el.closest('#preview-form')&&el.id!=='allow-partial'&&el.id!=='keep-similar'){state.previewDirty=true;$('#preview-dirty-note').hidden=false;}
    if(el.closest('#preview-form'))updateConfirm();
    if(el.dataset.selection){const id=Number(el.dataset.selection);if(el.checked)state.selected.add(id);else state.selected.delete(id);selectedUI();}
    if(el.id==='select-page'){document.querySelectorAll('[data-selection]:not(:disabled)').forEach(c=>{c.checked=el.checked;const id=Number(c.dataset.selection);if(el.checked)state.selected.add(id);else state.selected.delete(id);});selectedUI();}
    if(el.name==='conteudo'&&el.closest('#export-form')){const forecast=el.value==='forecast';$('#export-filters').hidden=forecast;$('#export-horizon').hidden=!forecast;}
  }catch(error){toast(error.message,true);}
});
document.addEventListener('dragover',event=>{const zone=event.target.closest('#upload-zone');if(zone){event.preventDefault();zone.classList.add('dragover');}});
document.addEventListener('dragleave',event=>{const zone=event.target.closest('#upload-zone');if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove('dragover');});
document.addEventListener('drop',event=>{const zone=event.target.closest('#upload-zone');if(zone){event.preventDefault();zone.classList.remove('dragover');uploadFile(event.dataTransfer.files[0]).catch(error=>toast(error.message,true));}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!modal.open){event.preventDefault();$('#global-search input').focus();}if(event.key==='Escape'){closeSidebar();$('#notification-panel').hidden=true;}});
document.addEventListener('click',event=>{if(!event.target.closest('#notification-panel')&&!event.target.closest('[data-action="notifications"]'))$('#notification-panel').hidden=true;});
$('#sidebar-backdrop').addEventListener('click',closeSidebar);
$('#skip-link').addEventListener('click',event=>{event.preventDefault();main.focus();});
modal.addEventListener('click',event=>{if(event.target===modal&&event.offsetX>=0&&(event.offsetX>modal.clientWidth||event.offsetY>modal.clientHeight))modal.close();});
window.addEventListener('hashchange',()=>{closeSidebar();render();});
decorate();
loadCompanies().then(render).catch(error=>{main.innerHTML=`<div class="fatal-view"><h2>Seu espaço não pôde ser carregado.</h2><p>${esc(error.message)}</p>${button('Tentar novamente','retry','refresh','secondary')}</div>`;});
